#!/usr/bin/env node
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    —
 * depends    —
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/**
 * Enforces the package's structural conventions.
 *
 * Types and tests check behaviour; this checks shape — that every public module
 * is reachable, that names are predictable, and that nothing is a one-off. The
 * point is that a contributor (or an agent) can infer the rest of the package
 * from any one file, because every file follows the same rules.
 *
 * Exit codes: 0 = clean, 1 = violations.
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const SRC = path.join(ROOT, 'src')
const norm = p => p.split(path.sep).join('/')

/** Areas with a public barrel. Everything else is internal. */
const PUBLIC_AREAS = ['data', 'save', 'node', 'formatting', 'mechanics']

/** Generated tables are allowed to be enormous; hand-written code is not. */
const MAX_LINES = 1200
/*
 * `knowledge/compartments/` is in this list as a class, not by the words in its filenames.
 * A compartment is a catalog of facts about one system — the same kind of file as the data
 * catalogs above it, and it grows with the game rather than with anyone's design. Until now
 * `compartments/modules.ts` and `compartments/cards.ts` were exempt and `compartments/enemies.ts`
 * was not, purely because `modules` and `cards` happen to appear in this pattern for an
 * unrelated reason. Splitting one sibling and not the others would make the set less readable,
 * not more.
 */
const GENERATED = /(generated|catalog|-tables|-data|knowledge\/compartments\/|player-stats|labs-research|labs-levels|workshop|reference|indexes|assets|relics|modules|cards|perks|tiers|substats|chart|milestones|schemas|vocabulary)/i

const problems = []
const files = []
const walk = dir => {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = norm(path.join(dir, entry.name))
    if (entry.isDirectory()) walk(p)
    else if (entry.name.endsWith('.ts')) files.push(p)
  }
}
walk(SRC)

/**
 * Monorepo / Node-only surfaces — not on the published public barrel.
 * (export* of these pulls node:fs into browser bundles and blanks the showcase site.)
 */
const MONOREPO_ONLY = rel =>
  rel.startsWith('mechanics/doctor/')
  || rel.startsWith('mechanics/kernel/')
  || rel.startsWith('mechanics/sandbox/')
  || rel.startsWith('mechanics/docs-gen/')
  || rel.startsWith('mechanics/lsp/')
  || rel.startsWith('mechanics/registry/')
  || rel.startsWith('mechanics/coverage/')
  || rel.startsWith('mechanics/debug-graph/')
  || rel.startsWith('mechanics/ep-graph/')
  || rel.startsWith('mechanics/save-graph/')
  || rel.startsWith('mechanics/sdk-graph/')
  || rel.startsWith('mechanics/planner-engine/')
  || rel.startsWith('mechanics/builders/')
  || rel === 'mechanics/governance-adapter.ts'
  || rel === 'mechanics/repo-root.ts'
  || rel === 'mechanics/mcp-contract.ts'
  || rel.startsWith('mechanics/sdk-graph/sheet-drift-mutate')
  || rel.startsWith('mechanics/planner-engine/generated/')

for (const file of files) {
  const rel = norm(path.relative(SRC, file))
  if (MONOREPO_ONLY(rel)) continue
  const base = path.basename(rel)
  const raw = fs.readFileSync(file, 'utf8')
  const isTest = base.endsWith('.test.ts')
  // Doc comments show consumers the published specifier; that is not an import.
  const source = raw.replace(/\/\*[\s\S]*?\*\//g, '').replace(/^\s*\/\/.*$/gm, '')

  // 1. kebab-case names.
  // `.generated.ts` marks emitted files, and tests may carry a descriptive
  // qualifier (`wave-base-scaling.t10-parity.test.ts`). Both are intentional.
  const stem = base.replace(/\.test\.ts$|\.generated\.ts$|\.ts$/, '')
  const segments = isTest ? stem.split('.') : [stem]
  for (const segment of segments) {
    if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(segment) && !segment.startsWith('_')) {
      problems.push(`${rel}: file name is not kebab-case`)
      break
    }
  }

  // 2. No default exports — they make re-exports and tooling unpredictable.
  if (/^export default/m.test(source)) {
    problems.push(`${rel}: uses a default export; this package is named-exports only`)
  }

  // 3. Never import the barrel of your own area — that is a cycle.
  const area = rel.split('/')[0]
  if (PUBLIC_AREAS.includes(area) && base !== 'index.ts' && !isTest) {
    if (/from '\.\/index'/.test(source) || new RegExp(`from '\\.\\./${area}/index'`).test(source)) {
      problems.push(`${rel}: imports its own area barrel; import the sibling module directly`)
    }
  }

  // 4. The package must never import itself by name.
  if (/from '(thetowersdk[^']*)'/.test(source) && !isTest) {
    const m = source.match(/from '(thetowersdk[^']*)'/)
    problems.push(`${rel}: imports ${m[1]}; inside src/ use a relative path`)
  }

  /*
   * 5. Published files state what is true, never how it was established.
   *
   * This package is distributed. Working notes about tooling, internal paths
   * and research method are not part of what it asserts, and they age badly:
   * a reader six months from now needs the fact and the version it applies to,
   * not a trail through someone's scratch directory.
   *
   * Checked against the RAW text, comments included — a doc comment ships just
   * as surely as a string literal does.
   *
   * **A game version is not a trail.** `v28.3.0-arm64` is the build a fact was
   * verified against, which is precisely the "version it applies to" this rule
   * asks for — so a version token is removed before the patterns run. Without
   * that, `-arm64` fired on twelve files whose only sin was answering the
   * question the rule poses, and the fix would have been to delete the
   * provenance that makes a claim checkable.
   */
  const trail = raw.replace(/\bv\d+(?:\.\d+)*-arm64\b/gi, ' <GAME_VERSION> ')

  const INTERNAL_TRAIL = [
    [/extraction-core/i, 'an internal tooling path'],
    [/\bdumps?\//i, 'an internal artefact path'],
    [/\bdump\.cs\b/i, 'an internal artefact filename'],
    [/\bil2cpp\b/i, 'internal tooling'],
    [/\brodata\b/i, 'internal tooling'],
    [/\bdisassembl/i, 'internal method'],
    [/\bdecompil/i, 'internal method'],
    [/-arm64\b/i, 'an internal build identifier'],
  ]
  for (const [pattern, what] of INTERNAL_TRAIL) {
    if (pattern.test(trail)) {
      problems.push(
        `${rel}: mentions ${what} (${pattern.source}); published files describe what a thing IS, `
        + 'not how it was established — state the fact and its version instead',
      )
      break
    }
  }

  // 5. Nothing reaches outside the package. A fork has only what is committed here.
  for (const m of source.matchAll(/['"`](\.\.\/){3,}[^'"`]*['"`]/g)) {
    problems.push(`${rel}: reads ${m[0]}; a fork has no monorepo around it — keep fixtures in the package`)
  }

  // 6. Keep hand-written files readable.
  const lines = source.split('\n').length
  if (lines > MAX_LINES && !GENERATED.test(rel)) {
    problems.push(`${rel}: ${lines} lines; split it or name it so it reads as generated data`)
  }
}

// 7. Every public module is exported from its barrel.
for (const area of PUBLIC_AREAS) {
  const barrelPath = path.join(SRC, area, 'index.ts')
  if (!fs.existsSync(barrelPath)) {
    problems.push(`${area}/index.ts is missing`)
    continue
  }
  const barrel = fs.readFileSync(barrelPath, 'utf8')
  const modules = fs
    .readdirSync(path.join(SRC, area), { withFileTypes: true })
    .filter(e => e.isFile() && e.name.endsWith('.ts') && !e.name.endsWith('.test.ts') && e.name !== 'index.ts')
    .map(e => e.name.replace(/\.ts$/, ''))
    .filter(mod => !MONOREPO_ONLY(`${area}/${mod}.ts`))

  /**
   * A module also counts as reachable when a module the barrel *does* export
   * re-exports it. That is the real invariant — "nobody can import it" is false
   * when a public sibling passes it through.
   */
  const reachable = new Set()
  for (const mod of modules) {
    if (!barrel.includes(`'./${mod}'`)) continue
    reachable.add(mod)
    const source = fs.readFileSync(path.join(SRC, area, `${mod}.ts`), 'utf8')
    for (const match of source.matchAll(/from '\.\/([\w.-]+)'/g)) reachable.add(match[1])
  }

  for (const mod of modules) {
    if (!reachable.has(mod)) {
      problems.push(`${area}/${mod}.ts is not exported from ${area}/index.ts; nobody can import it`)
    }
  }
}

// 7. Extractors follow one shape.
const saveDir = path.join(SRC, 'save')
if (fs.existsSync(saveDir)) {
  for (const entry of fs.readdirSync(saveDir)) {
    if (!entry.endsWith('.ts') || entry.endsWith('.test.ts')) continue
    const source = fs.readFileSync(path.join(saveDir, entry), 'utf8')
    for (const m of source.matchAll(/export function (extract\w+FromSaveRoot)\s*\(([^)]*)\)\s*:\s*([^{]+)\{/g)) {
      const [, name, , returnType] = m
      // `T | null` is the rule for a record-shaped result. A collection result
      // (array, Partial, Record, Set, Map) signals "absent" by being empty,
      // which is friendlier than null and just as safe — allow it.
      const nullable = /\|\s*null/.test(returnType) || /\bnull\b/.test(returnType)
      const collection = /(\[\]|Partial<|Record<|ReadonlyArray<|Set<|Map<)/.test(returnType)
      if (!nullable && !collection) {
        problems.push(
          `save/${entry}: ${name} returns ${returnType.trim()}; use \`| null\` or an empty collection`,
        )
      }
    }
  }
}

if (problems.length) {
  console.error(`convention violations: ${problems.length}\n`)
  for (const p of problems.slice(0, 40)) console.error(`  ${p}`)
  if (problems.length > 40) console.error(`  ... and ${problems.length - 40} more`)
  process.exit(1)
}
console.log(`conventions OK (${files.length} files checked)`)
